const writtenGainWrites = `-- name: WrittenGainWrites :many
SELECT g.id, g.track_id, g.album, g.ord, g.root, g.rel_path, g.track_gain, g.track_peak, g.album_gain, g.album_peak,
       g.prior, t.title
FROM gain_writes g
LEFT JOIN tracks t ON t.id = g.track_id
WHERE g.run_id = ? AND g.state = 'written'
ORDER BY g.ord, g.id
`

type WrittenGainWritesRow struct {
	ID        int64
	TrackID   *int64
	Album     string
	Ord       int64
	Root      string
	RelPath   string
	TrackGain float64
	TrackPeak float64
	AlbumGain *float64
	AlbumPeak *float64
	Prior     string
	Title     *string
}

// What a run wrote, for its undo, with where each song is now.
func (q *Queries) WrittenGainWrites(ctx context.Context, runID int64) ([]WrittenGainWritesRow, error) {
	rows, err := q.query(ctx, q.writtenGainWritesStmt, writtenGainWrites, runID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WrittenGainWritesRow
	for rows.Next() {
		var i WrittenGainWritesRow
		if err := rows.Scan(
			&i.ID,
			&i.TrackID,
			&i.Album,
			&i.Ord,
			&i.Root,
			&i.RelPath,
			&i.TrackGain,
			&i.TrackPeak,
			&i.AlbumGain,
			&i.AlbumPeak,
			&i.Prior,
			&i.Title,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
